use super::network_codegen as codec;
use dlm_core::{load_program_with_paths,lower_program,parse_module_with_source,CheckPolicy,FileId,SourceFile};
use dlm_core::ast::ImportDecl;
use dlm_core::native::vm::{Value,Vm};
use dlm_core::native::Ty;
use dlm_network_proof::{NetworkSpecIR,NetworkExecutableIR,NetworkStateIR,NetworkTransitionIR,NetworkCertificate,NetworkProofIR,NetworkBudget,check_network_proof,check_bundle,runtime_bindings,source_matches,sha256};
use std::fmt::Write as _;
use std::path::{Path,PathBuf};
fn diagnostics(errors:Vec<dlm_core::Diagnostic>)->String{errors.iter().map(ToString::to_string).collect::<Vec<_>>().join("\n")}
fn machine(input:&Path,descriptor:&[u8],library:&Path,libs:&[PathBuf],minor:u32)->Result<NetworkExecutableIR,String>{
    let support=load_program_with_paths(&library.join("std/net_session_machine.dlm"),libs).map_err(diagnostics)?;let wire=load_program_with_paths(&library.join("std/net_spec_wire.dlm"),libs).map_err(diagnostics)?;codec::check_library(&support,library)?;codec::check_library(&wire,library)?;
    let program=if input.extension().and_then(|s|s.to_str())==Some("dns") {
        let mut root=support.root().clone();root.imports.push(ImportDecl{path:"std.net_spec_wire".into()});codec::linked(root,vec![support,wire])?
    }else{let schema=load_program_with_paths(input,libs).map_err(diagnostics)?;codec::check_library(&schema,library)?;let mut root=schema.root().clone();for name in ["std.net_session_machine","std.net_spec_wire"]{if !root.imports.iter().any(|i|i.path==name){root.imports.push(ImportDecl{path:name.into()});}}codec::linked(root,vec![schema,support,wire])?};
    let lowered=lower_program(&program,CheckPolicy::default()).map_err(diagnostics)?;let custom=lowered.native.unit.functions.iter().find(|f|f.name=="network_machine");if let Some(f)=custom{if !f.params.is_empty()||f.ret!=Ty::Record("ProtocolMachine".into())||f.unsafe_||f.body.is_none()||["NoAlloc","NoBlocking","NoIO","BoundedWork"].iter().any(|s|!f.guarantees.contains(*s)){return Err("network_machine must be safe, no-argument and return ProtocolMachine with pure bounded guarantees".into());}}
    let mut vm=Vm::new(&lowered.native).with_step_limit(50_000_000);let decoded=vm.call("network_spec_decode",vec![Value::Slice(codec::byte_cells(descriptor),0,descriptor.len())])?;let spec=codec::member(&decoded,"spec")?;
    let value=if custom.is_some(){vm.call("network_machine",vec![])?}else{vm.call("protocol_default",vec![Value::Ref(codec::cell(spec.clone())),Value::U(minor as u64)])?};let checked=vm.call("protocol_machine_check",vec![Value::Ref(codec::cell(spec)),Value::Ref(codec::cell(value.clone())),Value::U(minor as u64)])?;
    if codec::number(&checked,"status")?!=0{return Err(format!("protocol machine rejected: state {}, transition {}",codec::number(&checked,"state")?,codec::number(&checked,"transition")?));}
    let count=codec::number(&value,"state_count")? as usize;let edges=codec::number(&value,"transition_count")? as usize;let mut states=Vec::new();let mut transitions=Vec::new();
    for state in codec::sequence(&codec::member(&value,"states")?)?.into_iter().take(count){states.push(NetworkStateIR(codec::words::<5>(&vm.call("protocol_state_words",vec![Value::Ref(codec::cell(state))])?)?));}
    for edge in codec::sequence(&codec::member(&value,"transitions")?)?.into_iter().take(edges){transitions.push(NetworkTransitionIR(codec::words::<8>(&vm.call("protocol_transition_words",vec![Value::Ref(codec::cell(edge))])?)?));}
    Ok(NetworkExecutableIR{initial:codec::number(&value,"initial")? as u32,states,transitions})
}
fn search(machine:&NetworkExecutableIR,properties:u32,budget:usize)->Result<NetworkProofIR,String>{
    let mut remaining=budget;let mut ranks=vec![u32::MAX;machine.states.len()];let initial=machine.index(machine.initial).ok_or("missing initial state")?;ranks[initial]=0;
    for distance in 0..machine.states.len(){for edge in &machine.transitions{if remaining==0{return Err("UnknownWithinBudget: protocol proof search budget exhausted".into());}remaining-=1;let from=machine.index(edge.0[0]).ok_or("missing source")?;let to=machine.index(edge.0[4]).ok_or("missing target")?;if ranks[from]==distance as u32 && ranks[to]==u32::MAX{ranks[to]=distance as u32+1;}}}
    if ranks.contains(&u32::MAX){return Err("unreachable protocol state".into());}let reachable=if ranks.len()==32{u32::MAX}else{(1u32<<ranks.len())-1};Ok(NetworkProofIR{reachable,ranks,properties})
}
fn render(model:&codec::Model,machine:&NetworkExecutableIR,module:&str,prefix:&str,minor:u32)->String{
    let mut out=format!("module {module}\nimport std.net_session\nnative {{\n");codec::emit_spec(&mut out,model,prefix);writeln!(out,"    fn {prefix}_machine() -> ProtocolMachine guarantees(NoAlloc,NoBlocking,NoIO,BoundedWork) {{\n        let mut machine: ProtocolMachine=protocol_machine();machine.initial={};machine.state_count={};machine.transition_count={};",machine.initial,machine.states.len(),machine.transitions.len()).unwrap();
    for(i,state)in machine.states.iter().enumerate(){let s=state.0;writeln!(out,"        machine.states[{i}]=ProtocolState({},{},{},{},{});",s[0],s[1],s[2],s[3]!=0,s[4]!=0).unwrap();}
    for(i,edge)in machine.transitions.iter().enumerate(){let t=edge.0;writeln!(out,"        machine.transitions[{i}]=ProtocolTransition({},{},{},{},{},{},{},{});",t[0],t[1],t[2],t[3],t[4],t[5],t[6],t[7]!=0).unwrap();}
    writeln!(out,"        return machine;\n    }}\n    fn {prefix}_open(initiator: Bool, choice: TransportChoice, target: TransportTarget, cancel: &Resource<OpaqueHandle,net_cancel_dispose>) -> ProtocolSession {{ return protocol_open({prefix}_spec(),{prefix}_machine(),{minor},initiator,choice,target,cancel); }}\n    fn {prefix}_adopt(transport: TransportSession, initiator: Bool) -> ProtocolSession {{ return protocol_adopt(move transport,{prefix}_spec(),{prefix}_machine(),{minor},initiator); }}\n}}").unwrap();out
}
fn identifier(s:&str,limit:usize)->bool{let mut chars=s.chars();s.len()<=limit && chars.next().map(|c|c.is_ascii_alphabetic()||c=='_').unwrap_or(false) && chars.all(|c|c.is_ascii_alphanumeric()||c=='_')}
fn generate(args:&[String])->Result<(),String>{
    let usage="dlm network-protocol SCHEMA.dlm|SPEC.dns --module generated.session --prefix Session -o session.dlm [--minor N] [--machine FILE.state] [--lib DIR] [--work N] [--force|--check]";
    let input=PathBuf::from(args.first().ok_or(usage)?);let(mut output,mut module,mut prefix,mut minor,mut binary_machine)=(PathBuf::new(),String::new(),String::new(),None,None);let(mut libs,mut force,mut check,mut budget)=(Vec::new(),false,false,NetworkBudget::default());let mut index=1;
    while index<args.len(){let option=&args[index];index+=1;if option=="--force"{force=true;continue;}if option=="--check"{check=true;continue;}let value=args.get(index).ok_or(usage)?;index+=1;match option.as_str(){"--module"=>module=value.clone(),"--prefix"=>prefix=value.clone(),"-o"|"--output"=>output=PathBuf::from(value),"--minor"=>minor=Some(value.parse::<u32>().map_err(|_|"invalid minor")?),"--lib"=>libs.push(PathBuf::from(value)),"--machine"=>binary_machine=Some(PathBuf::from(value)),"--work"=>budget.max_work=value.parse().map_err(|_|"invalid work budget")?,_=>return Err(usage.into())}}
    if !module.split('.').all(|s|identifier(s,128))||!identifier(&prefix,48)||output.extension().and_then(|s|s.to_str())!=Some("dlm")||(force&&check){return Err(usage.into());}
    let(model,library,libs)=codec::checked_schema(&input,&libs)?;let spec=NetworkSpecIR::from_bytes(&model.bytes).map_err(|e|e.to_string())?;let minor=minor.unwrap_or(spec.words[2]);if minor<spec.words[3]||minor>spec.words[2]{return Err("minor outside accepted window".into());}
    let machine=if let Some(path)=&binary_machine{NetworkExecutableIR::from_bytes(&codec::read_limited(path,8848)?).map_err(|e|e.to_string())?}else{machine(&input,&model.bytes,&library,&libs,minor)?};
    let proof=search(&machine,416|if spec.words[25]!=0{64}else{0},budget.max_work)?;let mut audit=check_network_proof(&spec,&machine,minor,&proof,budget).map_err(|e|e.to_string())?;let source=render(&model,&machine,&module,&prefix,minor);if source.len()>2*1024*1024{return Err("generated source exceeds 2 MiB".into());}source_matches(&source,&spec,&machine,minor,&module,&prefix).map_err(|e|e.to_string())?;
    let dependencies=runtime_bindings();for(name,hash)in &dependencies{if sha256(&codec::read_limited(&library.join(name),1024*1024)?)!=*hash{return Err(format!("runtime dependency changed since the network kernel was built: {name}"));}}
    let parsed=parse_module_with_source(&source,SourceFile::named(FileId::ROOT,&output)).map_err(diagnostics)?;let runtime=load_program_with_paths(&library.join("std/net_session.dlm"),&libs).map_err(diagnostics)?;codec::check_library(&runtime,&library)?;let program=codec::linked(parsed,vec![runtime])?;let lowered=lower_program(&program,CheckPolicy::allow_unsafe()).map_err(diagnostics)?;let mut vm=Vm::new(&lowered.native).with_step_limit(50_000_000);
    let schema=vm.call(&format!("{prefix}_spec"),vec![])?;let plan=vm.call(&format!("{prefix}_machine"),vec![])?;let validated=vm.call("protocol_machine_check",vec![Value::Ref(codec::cell(schema)),Value::Ref(codec::cell(plan)),Value::U(minor as u64)])?;if codec::number(&validated,"status")?!=0{return Err("generated machine failed the DLM validator".into());}
    let source_name=output.file_name().and_then(|s|s.to_str()).ok_or("source filename is not UTF-8")?.to_string();let source_sha256=sha256(source.as_bytes());let certificate=NetworkCertificate{module,prefix,minor,source_name,source_sha256:source_sha256.clone(),descriptor:model.bytes.clone(),executable:machine.to_bytes(),proof,dependencies,binary_sha256:None};let certificate_text=certificate.to_text();NetworkCertificate::from_text(&certificate_text,budget).map_err(|e|e.to_string())?;
    let suffix=|s:&str|PathBuf::from(format!("{}{s}",output.display()));let bundle=vec![(output.clone(),source.into_bytes()),(suffix(".dns"),model.bytes),(suffix(".state"),machine.to_bytes()),(suffix(".nproof"),certificate_text.into_bytes())];
    let mut protected=vec![input.canonicalize().map_err(|e|e.to_string())?];if let Some(path)=binary_machine{protected.push(path.canonicalize().map_err(|e|e.to_string())?);}for(name,_)in runtime_bindings(){protected.push(library.join(name).canonicalize().map_err(|e|e.to_string())?);}for(path,_)in &bundle{if let Ok(path)=path.canonicalize(){if !check && protected.contains(&path){return Err("output cannot replace input or a runtime dependency".into());}}}
    codec::write_bundle(&bundle,force,check)?;audit.source_sha256=source_sha256;println!("{}",audit.json());Ok(())
}
fn audit(args:&[String],bind:bool)->Result<(),String>{
    let path=PathBuf::from(args.first().ok_or("pass a .nproof certificate")?);let(mut library,mut binary,mut budget)=(None,None,NetworkBudget::default());let mut index=1;while index<args.len(){let option=&args[index];let value=args.get(index+1).ok_or("missing option value")?;match option.as_str(){"--lib"=>library=Some(PathBuf::from(value)),"--binary"=>binary=Some(PathBuf::from(value)),"--work"=>budget.max_work=value.parse().map_err(|_|"invalid work budget")?,_=>return Err("unknown certificate option".into())}index+=2;}
    let library=library.or_else(||std::env::var_os("DLM_PATH").and_then(|p|std::env::split_paths(&p).next())).unwrap_or_else(||PathBuf::from("lib"));
    if bind{let bytes=codec::read_limited(&path,512*1024)?;let text=std::str::from_utf8(&bytes).map_err(|_|"certificate is not UTF-8")?;let mut certificate=NetworkCertificate::from_text(text,budget).map_err(|e|e.to_string())?;let _report=check_bundle(&path,&library,if certificate.binary_sha256.is_some(){binary.as_deref()}else{None},budget).map_err(|e|e.to_string())?;let binary=binary.ok_or("network-bind requires --binary FILE")?;certificate.binary_sha256=Some(sha256(&codec::read_limited(&binary,256*1024*1024)?));codec::write_bundle(&[(path.clone(),certificate.to_text().into_bytes())],true,false)?;let report=check_bundle(&path,&library,Some(&binary),budget).map_err(|e|e.to_string())?;println!("{}",report.json());}
    else{let report=check_bundle(&path,&library,binary.as_deref(),budget).map_err(|e|e.to_string())?;println!("{}",report.json());}Ok(())
}
pub fn run(args:&[String]){finish(generate(args));}
pub fn run_audit(args:&[String]){finish(audit(args,false));}
pub fn run_bind(args:&[String]){finish(audit(args,true));}
fn finish(result:Result<(),String>){if let Err(error)=result{eprintln!("network protocol: {error}");std::process::exit(if error.contains("UnknownWithinBudget"){3}else{1});}}

pub fn is_certificate(path:&str)->bool{use std::io::Read;let mut header=[0u8;16];std::fs::File::open(path).and_then(|mut file|file.read_exact(&mut header)).is_ok() && &header==b"DLM-NET-PROOF v1"}
